async function all(t,q={}){const a=[];for(let offset=0;;offset+=1000){const p=await db(t,{order:'id.asc',...q,limit:1000,offset});a.push(...p);if(p.length<1000)return a;}}
const specs={leads:['crm_leads'],sms:['sms_messages'],followups:['crm_followup_logs'],tasks:['crm_tasks'],quotes:['crm_quotes'],emails:['crm_emails'],opportunities:['partner_opportunities'],referrals:['partner_referrals'],calls:['call_recordings',{order:'recording_sid.asc'}],touches:['market_touches',{select:'id,contact_id,channel,direction,created_at,notes,metadata'}],contacts:['market_contacts',{select:'id,name,phone,email,city,do_not_contact,cross_channel_suppressed_at,owner_name'}]};
